UPDATE `oc_setting` SET `value`='{"3": "\\u041a\\u0430\\u043a \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u043c\\u043e\\u0434\\u0443\\u043b\\u044c \\u043f\\u0435\\u0440\\u0435\\u0434 \\u043f\\u043e\\u043a\\u0443\\u043f\\u043a\\u043e\\u0439?|\\u041e\\u0442\\u043a\\u0440\\u043e\\u0439\\u0442\\u0435 \\u0434\\u0435\\u043c\\u043e-\\u0430\\u0434\\u043c\\u0438\\u043d\\u043a\\u0443 demo.codecartpro.com/admin (\\u043b\\u043e\\u0433\\u0438\\u043d \\u0438 \\u043f\\u0430\\u0440\\u043e\\u043b\\u044c: Demo) \\u0438 \\u043f\\u043e\\u0441\\u043c\\u043e\\u0442\\u0440\\u0438\\u0442\\u0435 \\u043d\\u0430\\u0441\\u0442\\u0440\\u043e\\u0439\\u043a\\u0438 \\u043c\\u043e\\u0434\\u0443\\u043b\\u044f. \\u0421\\u043e\\u0441\\u0442\\u0430\\u0432 \\u0434\\u0435\\u043c\\u043e \\u043c\\u043e\\u0436\\u0435\\u0442 \\u043c\\u0435\\u043d\\u044f\\u0442\\u044c\\u0441\\u044f.\\r\\n\\u041a\\u0430\\u043a\\u0438\\u0435 \\u0432\\u0435\\u0440\\u0441\\u0438\\u0438 OpenCart \\u0438 PHP \\u043f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u0438\\u0432\\u0430\\u044e\\u0442\\u0441\\u044f?|\\u0415\\u0441\\u043b\\u0438 \\u0432 \\u043a\\u0430\\u0440\\u0442\\u043e\\u0447\\u043a\\u0435 \\u043d\\u0435 \\u0443\\u043a\\u0430\\u0437\\u0430\\u043d\\u043e \\u0438\\u043d\\u043e\\u0435 \\u2014 OpenCart 3.0.x, ocStore 3.0.x \\u0438 PHP 7.4\\u20138.5. \\u041f\\u0435\\u0440\\u0435\\u0434 \\u0443\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u043e\\u0439 \\u0441\\u0434\\u0435\\u043b\\u0430\\u0439\\u0442\\u0435 \\u0440\\u0435\\u0437\\u0435\\u0440\\u0432\\u043d\\u0443\\u044e \\u043a\\u043e\\u043f\\u0438\\u044e \\u0438 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044c\\u0442\\u0435 \\u043c\\u043e\\u0434\\u0443\\u043b\\u044c \\u043d\\u0430 \\u0442\\u0435\\u0441\\u0442\\u043e\\u0432\\u043e\\u0439 \\u043a\\u043e\\u043f\\u0438\\u0438.\\r\\n\\u041a\\u0430\\u043a \\u043f\\u043e\\u043b\\u0443\\u0447\\u0438\\u0442\\u044c \\u043c\\u043e\\u0434\\u0443\\u043b\\u044c \\u043f\\u043e\\u0441\\u043b\\u0435 \\u043e\\u043f\\u043b\\u0430\\u0442\\u044b?|\\u041f\\u043e\\u0441\\u043b\\u0435 \\u0443\\u0441\\u043f\\u0435\\u0448\\u043d\\u043e\\u0439 \\u043e\\u043f\\u043b\\u0430\\u0442\\u044b \\u0432\\u044b \\u043f\\u043e\\u043b\\u0443\\u0447\\u0430\\u0435\\u0442\\u0435 \\u0444\\u0430\\u0439\\u043b, \\u0441\\u0441\\u044b\\u043b\\u043a\\u0443, \\u043a\\u043b\\u044e\\u0447 \\u0438\\u043b\\u0438 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044e, \\u043f\\u0440\\u0435\\u0434\\u0443\\u0441\\u043c\\u043e\\u0442\\u0440\\u0435\\u043d\\u043d\\u044b\\u0435 \\u0442\\u043e\\u0432\\u0430\\u0440\\u043e\\u043c. \\u041f\\u043e\\u0434\\u0440\\u043e\\u0431\\u043d\\u043e\\u0441\\u0442\\u0438 \\u2014 \\u043d\\u0430 \\u0441\\u0442\\u0440\\u0430\\u043d\\u0438\\u0446\\u0435 \\u00ab\\u041f\\u043e\\u043a\\u0443\\u043f\\u043a\\u0430, \\u043e\\u043f\\u043b\\u0430\\u0442\\u0430 \\u0438 \\u043f\\u043e\\u043b\\u0443\\u0447\\u0435\\u043d\\u0438\\u0435\\u00bb.\\r\\n\\u0427\\u0442\\u043e \\u0441 \\u043f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u043a\\u043e\\u0439 \\u0438 \\u0432\\u043e\\u0437\\u0432\\u0440\\u0430\\u0442\\u043e\\u043c?|\\u0423\\u0441\\u043b\\u043e\\u0432\\u0438\\u044f \\u043b\\u0438\\u0446\\u0435\\u043d\\u0437\\u0438\\u0438, \\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 \\u0433\\u0430\\u0440\\u0430\\u043d\\u0442\\u0438\\u0438 \\u0438 \\u0432\\u043e\\u0437\\u0432\\u0440\\u0430\\u0442\\u043e\\u0432 \\u043e\\u043f\\u0438\\u0441\\u0430\\u043d\\u044b \\u043d\\u0430 \\u0441\\u0442\\u0440\\u0430\\u043d\\u0438\\u0446\\u0435 \\u00ab\\u041b\\u0438\\u0446\\u0435\\u043d\\u0437\\u0438\\u044f, \\u0433\\u0430\\u0440\\u0430\\u043d\\u0442\\u0438\\u044f \\u0438 \\u0432\\u043e\\u0437\\u0432\\u0440\\u0430\\u0442\\u00bb.", "1": "\\u042f\\u043a \\u043f\\u0435\\u0440\\u0435\\u0432\\u0456\\u0440\\u0438\\u0442\\u0438 \\u043c\\u043e\\u0434\\u0443\\u043b\\u044c \\u043f\\u0435\\u0440\\u0435\\u0434 \\u043a\\u0443\\u043f\\u0456\\u0432\\u043b\\u0435\\u044e?|\\u0412\\u0456\\u0434\\u043a\\u0440\\u0438\\u0439\\u0442\\u0435 \\u0434\\u0435\\u043c\\u043e-\\u0430\\u0434\\u043c\\u0456\\u043d\\u043a\\u0443 demo.codecartpro.com/admin (\\u043b\\u043e\\u0433\\u0456\\u043d \\u0456 \\u043f\\u0430\\u0440\\u043e\\u043b\\u044c: Demo) \\u0442\\u0430 \\u043f\\u0435\\u0440\\u0435\\u0433\\u043b\\u044f\\u043d\\u044c\\u0442\\u0435 \\u043d\\u0430\\u043b\\u0430\\u0448\\u0442\\u0443\\u0432\\u0430\\u043d\\u043d\\u044f \\u043c\\u043e\\u0434\\u0443\\u043b\\u044f. \\u0421\\u043a\\u043b\\u0430\\u0434 \\u0434\\u0435\\u043c\\u043e \\u043c\\u043e\\u0436\\u0435 \\u0437\\u043c\\u0456\\u043d\\u044e\\u0432\\u0430\\u0442\\u0438\\u0441\\u044f.\\r\\n\\u042f\\u043a\\u0456 \\u0432\\u0435\\u0440\\u0441\\u0456\\u0457 OpenCart \\u0456 PHP \\u043f\\u0456\\u0434\\u0442\\u0440\\u0438\\u043c\\u0443\\u044e\\u0442\\u044c\\u0441\\u044f?|\\u042f\\u043a\\u0449\\u043e \\u0432 \\u043a\\u0430\\u0440\\u0442\\u0446\\u0456 \\u043d\\u0435 \\u0432\\u043a\\u0430\\u0437\\u0430\\u043d\\u043e \\u0456\\u043d\\u0448\\u0435 \\u2014 OpenCart 3.0.x, ocStore 3.0.x \\u0456 PHP 7.4\\u20138.5. \\u041f\\u0435\\u0440\\u0435\\u0434 \\u0432\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u043d\\u044f\\u043c \\u0437\\u0440\\u043e\\u0431\\u0456\\u0442\\u044c \\u0440\\u0435\\u0437\\u0435\\u0440\\u0432\\u043d\\u0443 \\u043a\\u043e\\u043f\\u0456\\u044e \\u0442\\u0430 \\u043f\\u0435\\u0440\\u0435\\u0432\\u0456\\u0440\\u0442\\u0435 \\u043c\\u043e\\u0434\\u0443\\u043b\\u044c \\u043d\\u0430 \\u0442\\u0435\\u0441\\u0442\\u043e\\u0432\\u0456\\u0439 \\u043a\\u043e\\u043f\\u0456\\u0457.\\r\\n\\u042f\\u043a \\u043e\\u0442\\u0440\\u0438\\u043c\\u0430\\u0442\\u0438 \\u043c\\u043e\\u0434\\u0443\\u043b\\u044c \\u043f\\u0456\\u0441\\u043b\\u044f \\u043e\\u043f\\u043b\\u0430\\u0442\\u0438?|\\u041f\\u0456\\u0441\\u043b\\u044f \\u0443\\u0441\\u043f\\u0456\\u0448\\u043d\\u043e\\u0457 \\u043e\\u043f\\u043b\\u0430\\u0442\\u0438 \\u0432\\u0438 \\u043e\\u0442\\u0440\\u0438\\u043c\\u0443\\u0454\\u0442\\u0435 \\u0444\\u0430\\u0439\\u043b, \\u043f\\u043e\\u0441\\u0438\\u043b\\u0430\\u043d\\u043d\\u044f, \\u043a\\u043b\\u044e\\u0447 \\u0430\\u0431\\u043e \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0456\\u044e, \\u043f\\u0435\\u0440\\u0435\\u0434\\u0431\\u0430\\u0447\\u0435\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u043e\\u043c. \\u041f\\u043e\\u0434\\u0440\\u043e\\u0431\\u0438\\u0446\\u0456 \\u2014 \\u043d\\u0430 \\u0441\\u0442\\u043e\\u0440\\u0456\\u043d\\u0446\\u0456 \\u00ab\\u041a\\u0443\\u043f\\u0456\\u0432\\u043b\\u044f, \\u043e\\u043f\\u043b\\u0430\\u0442\\u0430 \\u0442\\u0430 \\u043e\\u0442\\u0440\\u0438\\u043c\\u0430\\u043d\\u043d\\u044f\\u00bb.\\r\\n\\u0429\\u043e \\u0437 \\u043f\\u0456\\u0434\\u0442\\u0440\\u0438\\u043c\\u043a\\u043e\\u044e \\u0442\\u0430 \\u043f\\u043e\\u0432\\u0435\\u0440\\u043d\\u0435\\u043d\\u043d\\u044f\\u043c?|\\u0423\\u043c\\u043e\\u0432\\u0438 \\u043b\\u0456\\u0446\\u0435\\u043d\\u0437\\u0456\\u0457, \\u0442\\u0435\\u0445\\u043d\\u0456\\u0447\\u043d\\u043e\\u0457 \\u0433\\u0430\\u0440\\u0430\\u043d\\u0442\\u0456\\u0457 \\u0442\\u0430 \\u043f\\u043e\\u0432\\u0435\\u0440\\u043d\\u0435\\u043d\\u044c \\u043e\\u043f\\u0438\\u0441\\u0430\\u043d\\u043e \\u043d\\u0430 \\u0441\\u0442\\u043e\\u0440\\u0456\\u043d\\u0446\\u0456 \\u00ab\\u041b\\u0456\\u0446\\u0435\\u043d\\u0437\\u0456\\u044f, \\u0433\\u0430\\u0440\\u0430\\u043d\\u0442\\u0456\\u044f \\u0442\\u0430 \\u043f\\u043e\\u0432\\u0435\\u0440\\u043d\\u0435\\u043d\\u043d\\u044f\\u00bb.", "2": "How can I try a module before buying?|Open the demo admin at demo.codecartpro.com/admin (login and password: Demo) and review the module settings. The demo contents may change.\\r\\nWhich OpenCart and PHP versions are supported?|Unless the product page says otherwise: OpenCart 3.0.x, ocStore 3.0.x and PHP 7.4\\u20138.5. Back up first and test on a staging copy.\\r\\nHow do I receive the module after payment?|After a successful payment you receive the file, link, key or instructions provided with the product. See the \\u201cPurchase, payment and delivery\\u201d page.\\r\\nWhat about support and refunds?|License, technical warranty and refund terms are described on the \\u201cLicense, warranty and refunds\\u201d page."}' WHERE `store_id`=0 AND `key`='theme_codecart_pro_product_faq';
UPDATE `oc_setting` SET `value`='{"1": "\\u0414\\u0435\\u043c\\u043e \\u043f\\u0435\\u0440\\u0435\\u0434 \\u043a\\u0443\\u043f\\u0456\\u0432\\u043b\\u0435\\u044e|\\u0411\\u0435\\u0437\\u043f\\u0435\\u0447\\u043d\\u0430 \\u043e\\u043f\\u043b\\u0430\\u0442\\u0430|OpenCart / ocStore 3.x|\\u041f\\u0456\\u0434\\u0442\\u0440\\u0438\\u043c\\u043a\\u0430", "3": "\\u0414\\u0435\\u043c\\u043e \\u043f\\u0435\\u0440\\u0435\\u0434 \\u043f\\u043e\\u043a\\u0443\\u043f\\u043a\\u043e\\u0439|\\u0411\\u0435\\u0437\\u043e\\u043f\\u0430\\u0441\\u043d\\u0430\\u044f \\u043e\\u043f\\u043b\\u0430\\u0442\\u0430|OpenCart / ocStore 3.x|\\u041f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u043a\\u0430", "2": "Demo before purchase|Secure payment|OpenCart / ocStore 3.x|Support"}' WHERE `store_id`=0 AND `key`='theme_codecart_pro_product_trust_badges';
UPDATE `oc_setting` SET `value`='{"1": "\\u041f\\u0456\\u0441\\u043b\\u044f \\u0443\\u0441\\u043f\\u0456\\u0448\\u043d\\u043e\\u0457 \\u043e\\u043f\\u043b\\u0430\\u0442\\u0438 \\u0432\\u0438 \\u043e\\u0442\\u0440\\u0438\\u043c\\u0443\\u0454\\u0442\\u0435 \\u0444\\u0430\\u0439\\u043b, \\u043f\\u043e\\u0441\\u0438\\u043b\\u0430\\u043d\\u043d\\u044f, \\u043a\\u043b\\u044e\\u0447 \\u0430\\u0431\\u043e \\u0456\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0456\\u044e, \\u043f\\u0435\\u0440\\u0435\\u0434\\u0431\\u0430\\u0447\\u0435\\u043d\\u0456 \\u0442\\u043e\\u0432\\u0430\\u0440\\u043e\\u043c. \\u0424\\u0456\\u0437\\u0438\\u0447\\u043d\\u0430 \\u0434\\u043e\\u0441\\u0442\\u0430\\u0432\\u043a\\u0430 \\u043d\\u0435 \\u043f\\u043e\\u0442\\u0440\\u0456\\u0431\\u043d\\u0430.", "3": "\\u041f\\u043e\\u0441\\u043b\\u0435 \\u0443\\u0441\\u043f\\u0435\\u0448\\u043d\\u043e\\u0439 \\u043e\\u043f\\u043b\\u0430\\u0442\\u044b \\u0432\\u044b \\u043f\\u043e\\u043b\\u0443\\u0447\\u0430\\u0435\\u0442\\u0435 \\u0444\\u0430\\u0439\\u043b, \\u0441\\u0441\\u044b\\u043b\\u043a\\u0443, \\u043a\\u043b\\u044e\\u0447 \\u0438\\u043b\\u0438 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044e, \\u043f\\u0440\\u0435\\u0434\\u0443\\u0441\\u043c\\u043e\\u0442\\u0440\\u0435\\u043d\\u043d\\u044b\\u0435 \\u0442\\u043e\\u0432\\u0430\\u0440\\u043e\\u043c. \\u0424\\u0438\\u0437\\u0438\\u0447\\u0435\\u0441\\u043a\\u0430\\u044f \\u0434\\u043e\\u0441\\u0442\\u0430\\u0432\\u043a\\u0430 \\u043d\\u0435 \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442\\u0441\\u044f.", "2": "After a successful payment you receive the file, link, key or instructions provided with the product. No physical shipping is required."}' WHERE `store_id`=0 AND `key`='theme_codecart_pro_product_delivery_text';
